# test_gen/generator.py
def generate_tests(source_code):
    template = """import pytest
    
def test_{func_name}():
    assert {func_name}() == {{}}
"""
    # Simple heuristic to extract function name (real implementation would be more robust)
    func_name = "sample_function"
    if "def " in source_code:
        func_line = source_code.split("def ")[1].split("(")[0].strip()
        func_name = func_line
    
    return template.format(func_name=func_name)

# test_gen/validator.py
def validate_syntax(code):
    try:
        compile(code, '<string>', 'exec')
        return True
    except:
        return False

# test_gen/runner.py
import docker
import tempfile
import os

def run_tests_in_sandbox(test_code):
    client = docker.from_env()
    
    with tempfile.TemporaryDirectory() as temp_dir:
        test_file = os.path.join(temp_dir, "tests.py")
        with open(test_file, "w") as f:
            f.write(test_code)
        
        try:
            img, _ = client.images.build(path=".", dockerfile="Dockerfile.testenv", tag="testenv")
            container = client.containers.run(
                img,
                command=f"pytest {test_file} -v",
                volumes={temp_dir: {'bind': '/tests', 'mode': 'ro'}},
                working_dir="/tests",
                stderr=True,
                stdout=True,
                stream=True,
                remove=True
            )
            output = [line.decode() for line in container]
            return "\n".join(output)
        except docker.errors.BuildError as e:
            return f"Build error: {str(e)}"
        except docker.errors.ContainerError as e:
            return f"Container error: {str(e)}"

